// This file is the single business rule shared by the two read-only reports a
// frozen snapshot supports:
//
//   - source tracing (TraceSources) lists every root source with one
//     representative path per root, and
//   - snapshot comparison (CompareSnapshots) decides, for each dataset common
//     to two versions, whether that reachable root set changed.
//
// Both ask the same question — "which datasets without upstreams are reachable
// from this one by following direct upstream edges" — so they walk the same
// normalized adjacency through the one finder below. The comparison can never
// explain a root differently from a trace run against the same snapshot: its
// old/new root names are a strict projection of what traceRootSources returns.
package chainledger

import "sort"

// traceRootSources finds, for one dataset within an already validated
// adjacency, every root source reachable by following direct upstream edges:
// a dataset that itself has no upstream is a root and its own source, a root
// reached through several branches is reported exactly once, intermediates
// that still have upstreams never qualify, and roots in disconnected
// components are never reached.
//
// Every root carries one shortest path (fewest direct relations), beginning at
// the queried dataset, listing every intermediate, and ending at the root.
// Among equally short paths the choice is made element by element from the
// START of the path in UTF-8 byte order, at the first differing name — never
// by the last branch name. Roots reached through a shared intermediate each
// keep their own complete path. The returned entries are sorted by root name
// byte order, and every path is a fresh slice owned by the caller, so editing
// a returned report can never reach the adjacency or another report.
func traceRootSources(dataset string, adj adjacency) []SourceTrace {
	// Breadth-first walk from the queried dataset along direct upstream
	// edges. best[node] holds the shortest, tie-broken path from the query to
	// node; because every edge has the same weight, the first level at which
	// a node is reached is its shortest distance, and keeping only the
	// smallest candidate path per node preserves the global minimum.
	best := map[string][]string{dataset: {dataset}}
	frontier := []string{dataset}
	for len(frontier) > 0 {
		candidates := make(map[string][]string)
		for _, node := range frontier {
			for _, parent := range adj[node] {
				if _, seen := best[parent]; seen {
					continue
				}
				path := append(append([]string{}, best[node]...), parent)
				if current, ok := candidates[parent]; !ok || pathLess(path, current) {
					candidates[parent] = path
				}
			}
		}
		next := make([]string, 0, len(candidates))
		for node, path := range candidates {
			best[node] = path
			next = append(next, node)
		}
		frontier = next
	}

	sources := make([]SourceTrace, 0)
	for node, path := range best {
		if len(adj[node]) == 0 {
			sources = append(sources, SourceTrace{Root: node, Path: path})
		}
	}
	sort.Slice(sources, func(i, j int) bool { return sources[i].Root < sources[j].Root })
	return sources
}

// rootSources is the names-only projection of the shared finder: the sorted
// root names a snapshot comparison records as a dataset's old or new sources.
// It is deliberately computed through traceRootSources so that the
// comparison's roots are exactly the names a TraceSources query reports
// against the same snapshot, in the same byte order. A node without upstreams
// is itself a root and its own source; a root reached by more than one path
// counts once. The result is sorted by name and never nil.
func rootSources(node string, adj adjacency) []string {
	traces := traceRootSources(node, adj)
	roots := make([]string, 0, len(traces))
	for _, src := range traces {
		roots = append(roots, src.Root)
	}
	return roots
}

// pathLess compares two equal-purpose paths element by element from the start
// using plain string (UTF-8 byte) order, deciding on the first differing
// name. A strict prefix counts as smaller, matching lexicographic order.
func pathLess(a, b []string) bool {
	for i := 0; i < len(a) && i < len(b); i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return len(a) < len(b)
}

// Package chainledger implements the on-chain data governance core.
//
// This file adds local lineage snapshots: a snapshot freezes one graph as a
// versioned, content-addressed JSON document, and two snapshots can be compared
// read-only. Every byte a snapshot writes is determined solely by the graph's
// semantics — dataset names and their direct upstreams — never by record
// order, upstream order, duplicate upstreams, JSON whitespace, save time, or
// file path.
package chainledger

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"sort"
)

// SnapshotFormatVersion is the only on-disk snapshot format understood.
const SnapshotFormatVersion = 1

// SnapshotFile is the on-disk representation of one frozen lineage graph.
//
// FormatVersion is fixed at 1. ContentID addresses the graph semantics and is
// verified against Graph on every read; Graph carries the complete graph.
type SnapshotFile struct {
	FormatVersion int       `json:"formatVersion"`
	ContentID     string    `json:"contentId"`
	Graph         GraphFile `json:"graph"`
}

// RootSourceChange reports that one dataset present in BOTH versions reaches a
// different set of root sources. OldRoots and NewRoots are sorted by name and
// never nil, so empty root sets encode as [] rather than null.
type RootSourceChange struct {
	Dataset  string   `json:"dataset"`
	OldRoots []string `json:"oldRoots"`
	NewRoots []string `json:"newRoots"`
}

// CompareReport is the deterministic, read-only diff of two snapshots read in
// the fixed direction old -> new.
//
// NewDatasets and RemovedDatasets list nodes present on only one side.
// ChangedDatasets lists datasets present on both sides whose direct upstream
// set actually changed. AddedRelations and RemovedRelations list every
// directed edge present on only one side, including edges that vanish because
// one endpoint node was removed. RootSourceChanges covers only datasets common
// to both versions whose reachable root set differs; added or removed datasets
// never appear there.
type CompareReport struct {
	NewDatasets       []string           `json:"newDatasets"`
	RemovedDatasets   []string           `json:"removedDatasets"`
	ChangedDatasets   []string           `json:"changedDatasets"`
	AddedRelations    []Relation         `json:"addedRelations"`
	RemovedRelations  []Relation         `json:"removedRelations"`
	RootSourceChanges []RootSourceChange `json:"rootSourceChanges"`
}

// contentIDPrefix names the hash algorithm used for content addressing.
const contentIDPrefix = "sha256:"

// canonicalGraph serializes the graph's semantics deterministically: datasets
// sorted by name byte order with sorted, duplicate-free upstream lists, compact
// JSON with no insignificant whitespace. Two semantically equal graphs always
// produce identical bytes.
func canonicalGraph(adj adjacency) ([]byte, error) {
	gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
	return json.Marshal(gf)
}

// computeContentID returns the content identifier of the graph bytes:
// "sha256:" followed by the lowercase hex SHA-256 digest.
func computeContentID(canonical []byte) string {
	sum := sha256.Sum256(canonical)
	return contentIDPrefix + hex.EncodeToString(sum[:])
}

// BuildSnapshot validates graph and freezes it into a SnapshotFile with format
// version 1 and the matching content identifier. It does not mutate graph. The
// returned document and its serialized bytes depend only on graph semantics.
//
// A dataset name or direct upstream reference that is not valid UTF-8 rejects
// the build with no snapshot and no content identifier: such bytes could not be
// serialized without silently rewriting the name, so the frozen document would
// not be a faithful, readable copy of the graph.
func BuildSnapshot(graph map[string]*Lineage) (*SnapshotFile, error) {
	// One read of the existing graph settles its legality and yields the
	// canonical relations the snapshot freezes — the same shared judgment
	// ValidateGraph, preview, apply, and graph export make.
	adj, err := validatedGraphAdjacency(graph)
	if err != nil {
		return nil, err
	}
	canonical, err := canonicalGraph(adj)
	if err != nil {
		return nil, err
	}
	return &SnapshotFile{
		FormatVersion: SnapshotFormatVersion,
		ContentID:     computeContentID(canonical),
		Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
	}, nil
}

// MarshalSnapshot serializes a snapshot the same way for every save: indented
// JSON keyed by struct field order, terminated by a single newline.
func MarshalSnapshot(snap *SnapshotFile) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetIndent("", "  ")
	enc.SetEscapeHTML(false)
	if err := enc.Encode(snap); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// rawSnapshot mirrors SnapshotFile but keeps each field raw so ParseSnapshot
// can distinguish "field absent" from "field present with a zero value"
// (e.g. a missing formatVersion must be rejected rather than read as 0).
type rawSnapshot struct {
	FormatVersion json.RawMessage `json:"formatVersion"`
	ContentID     json.RawMessage `json:"contentId"`
	Graph         json.RawMessage `json:"graph"`
}

// isJSONNull reports whether a raw JSON value is the literal null.
func isJSONNull(raw json.RawMessage) bool {
	return string(bytes.TrimSpace(raw)) == "null"
}

// ParseSnapshot parses and strictly validates one snapshot document: required
// fields must be present and well-typed, no known field may be declared twice
// within the same object (even with identical values, a null first, or a
// spelling equivalent under Unicode case folding or JSON escaping), the
// format version must be supported, the embedded graph must be structurally
// valid (no empty names, duplicate datasets, missing upstreams, or cycles),
// and the content identifier must correspond exactly to the graph. A
// tampered, corrupt, or otherwise invalid snapshot is rejected, so a bad file
// can never be trusted as a version.
func ParseSnapshot(data []byte) (*SnapshotFile, error) {
	if err := checkDuplicateFields(data); err != nil {
		return nil, err
	}
	var raw rawSnapshot
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("invalid snapshot JSON: %w", err)
	}
	if len(raw.FormatVersion) == 0 {
		return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "formatVersion")
	}
	if len(raw.ContentID) == 0 {
		return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "contentId")
	}
	if len(raw.Graph) == 0 {
		return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "graph")
	}
	// An explicit JSON null is present-but-untyped and must not be silently
	// treated as a zero value (in particular, graph:null must not read as an
	// empty graph).
	if isJSONNull(raw.FormatVersion) {
		return nil, fmt.Errorf("%w: snapshot field %q must be a number, not null", ErrInvalidArgument, "formatVersion")
	}
	if isJSONNull(raw.ContentID) {
		return nil, fmt.Errorf("%w: snapshot field %q must be a string, not null", ErrInvalidArgument, "contentId")
	}
	if isJSONNull(raw.Graph) {
		return nil, fmt.Errorf("%w: snapshot field %q must be an object, not null", ErrInvalidArgument, "graph")
	}

	var version int
	if err := json.Unmarshal(raw.FormatVersion, &version); err != nil {
		return nil, fmt.Errorf("%w: snapshot field %q must be a number: %v", ErrInvalidArgument, "formatVersion", err)
	}
	if version != SnapshotFormatVersion {
		return nil, fmt.Errorf("%w: unsupported snapshot format version %d, supported version is %d", ErrInvalidArgument, version, SnapshotFormatVersion)
	}

	var contentID string
	if err := json.Unmarshal(raw.ContentID, &contentID); err != nil {
		return nil, fmt.Errorf("%w: snapshot field %q must be a string", ErrInvalidArgument, "contentId")
	}
	if contentID == "" {
		return nil, fmt.Errorf("%w: snapshot field %q must not be empty", ErrInvalidArgument, "contentId")
	}

	// The embedded graph is decoded and checked by the one pipeline a
	// standalone graph file uses (see graph_document.go): the raw
	// name-encoding gate runs first on the graph's own bytes and rejects the
	// whole snapshot even when the declared content identifier happens to
	// match the rewritten graph's digest, then one JSON decode and the shared
	// structure rules (empty names, duplicate datasets, missing upstreams,
	// cycles) produce the canonical adjacency. The only snapshot-specific part
	// is the wording of a graph that is not valid JSON.
	adj, err := readGraphDocument(raw.Graph, "invalid graph in snapshot")
	if err != nil {
		return nil, err
	}

	canonical, err := canonicalGraph(adj)
	if err != nil {
		return nil, err
	}
	if want := computeContentID(canonical); contentID != want {
		return nil, fmt.Errorf("%w: content identifier %q does not match the graph (expected %q); the snapshot was altered or corrupted", ErrInvalidArgument, contentID, want)
	}

	return &SnapshotFile{
		FormatVersion: version,
		ContentID:     contentID,
		Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
	}, nil
}

// checkDuplicateFields applies the shared repeated-known-field rule (see
// duplicate_fields.go) to a snapshot, supplying the snapshot's own field
// scope and locations: formatVersion, contentId, and graph at the top level,
// datasets inside graph, and name and upstreams inside each dataset record.
// The embedded graph is scanned by the same checkGraphObject a standalone
// graph file uses, so the two readers can never judge one graph differently.
func checkDuplicateFields(data []byte) error {
	return runFieldScan(data, func(dec *json.Decoder) error {
		return checkObjectFields(dec, "at the top level of the snapshot", []knownField{
			{name: "formatVersion"},
			{name: "contentId"},
			{name: "graph", nested: func(dec *json.Decoder) error {
				return checkGraphObject(dec, `in "graph"`)
			}},
		})
	})
}

// CompareSnapshots returns the fixed-direction diff from old to new. Both
// inputs are assumed to have passed ParseSnapshot; the report is fully
// deterministic and identical for semantically identical comparisons.
func CompareSnapshots(oldSnap, newSnap *SnapshotFile) *CompareReport {
	oldAdj := adjacencyFromValidFile(oldSnap.Graph)
	newAdj := adjacencyFromValidFile(newSnap.Graph)

	// Dataset-level changes follow the shared old -> new rule the batch report
	// uses (see diffDatasets), so comparing two snapshots classifies new,
	// removed, and directly changed datasets exactly the way previewing or
	// applying the batch that turns one version into the other does.
	newNodes, removedNodes, changedNodes := diffDatasets(oldAdj, newAdj)

	added, removed := diffRelations(oldAdj, newAdj)

	common := make([]string, 0)
	for name := range oldAdj {
		if _, ok := newAdj[name]; ok {
			common = append(common, name)
		}
	}
	sort.Strings(common)

	rootChanges := make([]RootSourceChange, 0)
	for _, name := range common {
		oldRoots := rootSources(name, oldAdj)
		newRoots := rootSources(name, newAdj)
		if !stringSliceEqual(oldRoots, newRoots) {
			rootChanges = append(rootChanges, RootSourceChange{
				Dataset:  name,
				OldRoots: oldRoots,
				NewRoots: newRoots,
			})
		}
	}

	return &CompareReport{
		NewDatasets:       orEmptyStrings(newNodes),
		RemovedDatasets:   orEmptyStrings(removedNodes),
		ChangedDatasets:   orEmptyStrings(changedNodes),
		AddedRelations:    orEmptyRelations(added),
		RemovedRelations:  orEmptyRelations(removed),
		RootSourceChanges: rootChanges,
	}
}

// adjacencyFromValidFile builds normalized parent adjacency from an already
// validated graph file.
func adjacencyFromValidFile(gf GraphFile) adjacency {
	adj := make(adjacency, len(gf.Datasets))
	for _, ds := range gf.Datasets {
		adj[ds.Name] = uniqueSorted(ds.Upstreams)
	}
	return adj
}

func orEmptyStrings(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

func orEmptyRelations(r []Relation) []Relation {
	if r == nil {
		return []Relation{}
	}
	return r
}

// Package chainledger implements the on-chain data governance core.
package chainledger

import (
	"errors"
	"fmt"
	"sort"
)

// Sentinel errors so callers can recognize rejection reasons with errors.Is.
var (
	// ErrInvalidArgument is returned for malformed requests (empty names,
	// nil lineage nodes referenced as upstreams).
	ErrInvalidArgument = errors.New("invalid argument")
	// ErrNotFound is returned when an upstream dataset is not registered.
	ErrNotFound = errors.New("not found")
	// ErrCycle is returned when applying the registration would form a cycle.
	ErrCycle = errors.New("cycle detected")
	// ErrNotInitialized is returned when the graph map itself is nil.
	ErrNotInitialized = errors.New("lineage graph is not initialized")
)

// Dataset is one ingestible on-chain data source with a declared schema version.
type Dataset struct {
	Name          string
	SchemaVersion int
	Rows          int
	Upstreams     []string
}

// Lineage records where a dataset came from, so every derived table can be traced.
// Parents and Children are always sorted by name and free of duplicates.
type Lineage struct {
	Dataset  string
	Parents  []string
	Children []string
}

// Register links a dataset into the lineage graph.
//
// Registering an existing dataset name REPLACES its direct upstream (parent)
// relationships with the given parents:
//   - downstream (child) relationships of the dataset are preserved;
//   - parents dropped from the list no longer list the dataset as a child;
//   - newly added parents list the dataset exactly once;
//   - a nil or empty parents slice removes every direct upstream, turning the
//     dataset into a root while keeping its downstream.
//
// Duplicate parent names count as one relationship, and the stored lineage is
// independent of the caller's slice: mutating parents after Register returns
// does not affect the graph.
//
// The relationship change is determined solely by the submitted dataset name
// and its new upstreams. A hand-constructed graph may have two independent
// Lineage records whose Children (or Parents) slices share one backing array,
// overlap in a sub-slice window, or carry spare capacity another record's
// list occupies. Such a graph is legal as long as names correspond and no
// reference or cycle is missing, so Register never edits those name lists in
// place: a parent list that gains or loses the dataset receives a freshly
// allocated, independent slice (see withName and withoutName). Removing one
// upstream can therefore never shift or duplicate names another record's
// list shares, and adding one can never overwrite a name living in spare
// capacity. Records of datasets not involved in the change keep their
// previous contents.
//
// Registration is atomic. If any parent is missing or the resulting graph
// would contain a cycle (including a dataset depending on itself, directly or
// through other nodes), no node and no parent/child record is changed. Cycle
// validation uses the relationships as they will be AFTER the replacement, so
// an edge removed by this registration cannot make a legal change fail.
func Register(graph map[string]*Lineage, dataset Dataset, parents []string) error {
	if graph == nil {
		return fmt.Errorf("%w: create the graph map with make before registering datasets", ErrNotInitialized)
	}
	if dataset.Name == "" {
		return fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
	}

	// Normalize on a copy: dedupe (duplicates are one relationship), sort,
	// and detach from the caller's backing array.
	wanted := uniqueSorted(parents)
	for _, parent := range wanted {
		entry, ok := graph[parent]
		if !ok {
			return fmt.Errorf("%w: upstream dataset %q is not registered", ErrNotFound, parent)
		}
		if entry == nil {
			return fmt.Errorf("%w: upstream dataset %q points to a nil lineage node", ErrInvalidArgument, parent)
		}
	}

	// Snapshot the relationships this commit changes on independent slices
	// BEFORE mutating anything. The commit decides from these copies which
	// edges are kept, added, and removed, and reassigns the dataset's own
	// lists to them; stored lists of other records (which may share backing
	// storage) are never resliced in place.
	current, existed := graph[dataset.Name]
	var oldParents, oldChildren []string
	if current != nil {
		oldParents = append(oldParents, current.Parents...)
		// Normalize the preserved downstream on the copy as well, so a
		// hand-edited unsorted or duplicated list is repaired without an
		// in-place write.
		oldChildren = uniqueSorted(current.Children)
	}

	// Adding an edge dataset -> parent creates a cycle exactly when parent
	// can already reach the dataset by following parent edges in the
	// post-replacement graph.
	for _, parent := range wanted {
		if reachesAfterReplacement(graph, dataset.Name, wanted, parent, dataset.Name) {
			return fmt.Errorf("%w: dataset %q cannot depend on %q, it would reach itself", ErrCycle, dataset.Name, parent)
		}
	}

	// ---- All checks passed; commit below this line. ----
	//
	// No name list is edited in place. An in-place removal
	// (append(list[:i], list[i+1:]...)) shifts the shared backing array and
	// corrupts every other record whose list shares that storage — the removed
	// name lands in a neighbor's window and a kept name can duplicate or
	// vanish. In-place insertion is equally unsafe when the list has spare
	// capacity another record's list occupies. withName and withoutName
	// allocate independent slices instead.

	if !existed || current == nil {
		current = &Lineage{Dataset: dataset.Name}
		graph[dataset.Name] = current
	}
	current.Parents = wanted
	current.Children = oldChildren

	newSet := toSet(wanted)
	oldSet := toSet(oldParents)

	// Dropped upstreams lose the dataset as a child. Every name list is
	// rewritten on a fresh slice (see withoutName): an in-place removal would
	// shift the shared backing array and corrupt another record's list that
	// happens to share that storage.
	for _, oldParent := range oldParents {
		if newSet[oldParent] {
			continue // relationship is kept; that record's list is not touched
		}
		if entry := graph[oldParent]; entry != nil {
			entry.Children = withoutName(entry.Children, dataset.Name)
		}
	}

	// Only newly added upstreams gain the dataset as a child, each listing it
	// exactly once. withName allocates a fresh slice, so spare capacity in the
	// stored list can never overwrite names another record's list occupies in
	// the same backing array. Kept upstreams already list the dataset and are
	// deliberately left alone, so an unrelated record sharing their list sees
	// no movement at all.
	for _, parent := range wanted {
		if oldSet[parent] {
			continue
		}
		entry := graph[parent]
		entry.Children = withName(entry.Children, dataset.Name)
	}

	return nil
}

// reachesAfterReplacement reports whether start can reach target by following
// parent edges. While walking, the parents of overrideNode are treated as
// overrideParents, which makes the traversal reflect the graph AS IT WILL BE
// after the pending registration rather than the graph being replaced.
func reachesAfterReplacement(graph map[string]*Lineage, overrideNode string, overrideParents []string, start, target string) bool {
	seen := map[string]bool{}
	var walk func(node string) bool
	walk = func(node string) bool {
		if node == target {
			return true
		}
		if seen[node] {
			return false
		}
		seen[node] = true

		var nextParents []string
		if node == overrideNode {
			nextParents = overrideParents
		} else if entry, ok := graph[node]; ok && entry != nil {
			nextParents = entry.Parents
		}
		for _, parent := range nextParents {
			if walk(parent) {
				return true
			}
		}
		return false
	}
	return walk(start)
}

// Roots lists datasets with no parents, sorted by name.
func Roots(graph map[string]*Lineage) []string {
	var roots []string
	for name, entry := range graph {
		if entry != nil && len(entry.Parents) == 0 {
			roots = append(roots, name)
		}
	}
	sort.Strings(roots)
	return roots
}

// uniqueSorted returns a sorted, duplicate-free copy of names. The result is
// nil when no name remains, so empty lineage stays empty.
func uniqueSorted(names []string) []string {
	if len(names) == 0 {
		return nil
	}
	seen := make(map[string]bool, len(names))
	out := make([]string, 0, len(names))
	for _, name := range names {
		if !seen[name] {
			seen[name] = true
			out = append(out, name)
		}
	}
	sort.Strings(out)
	return out
}

func toSet(names []string) map[string]bool {
	set := make(map[string]bool, len(names))
	for _, name := range names {
		set[name] = true
	}
	return set
}

// withName returns a NEW sorted, duplicate-free slice that is list with name
// inserted at its byte-order position. It never writes through list's backing
// array: that array may be shared with another record's name list (or may have
// spare capacity another record's window occupies), so an in-place insertion
// could overwrite names the other record still owns. Entries other than the
// insertion are copied verbatim; the returned slice has no spare capacity.
func withName(list []string, name string) []string {
	index := sort.SearchStrings(list, name)
	if index < len(list) && list[index] == name {
		// Already present; return an independent copy so callers can never
		// mutate a shared backing array through the result.
		return append([]string(nil), list...)
	}
	out := make([]string, 0, len(list)+1)
	out = append(out, list[:index]...)
	out = append(out, name)
	out = append(out, list[index:]...)
	return out
}

// withoutName returns a NEW sorted slice equal to list with name omitted (if
// present). Unlike an in-place append(list[:i], list[i+1:]...), it never
// shifts the original backing array, so removing a name from one record can
// not move or duplicate the names another record's list shares in the same
// storage. A list without the name — including one that becomes empty — is
// still returned as an independent slice (nil when empty, matching the
// package's empty-lineage convention).
func withoutName(list []string, name string) []string {
	index := sort.SearchStrings(list, name)
	if index >= len(list) || list[index] != name {
		return append([]string(nil), list...)
	}
	if len(list) == 1 {
		return nil
	}
	out := make([]string, 0, len(list)-1)
	out = append(out, list[:index]...)
	out = append(out, list[index+1:]...)
	return out
}

