243			t.Fatalf("new trace merge: %v", err)
244		}
245		if got, want := oldMerge.Sources, []SourceTrace{
246			{Root: "rootA", Path: []string{"merge", "a1", "rootA"}},
247			{Root: "rootB", Path: []string{"merge", "b1", "rootB"}},
248			{Root: "rootC", Path: []string{"merge", "a2", "rootC"}},
