253			{Root: "rootA", Path: []string{"merge", "rootA"}},
254			{Root: "rootB", Path: []string{"merge", "b1", "rootB"}},
255			{Root: "rootC", Path: []string{"merge", "a2", "rootC"}},
256		}; !reflect.DeepEqual(got, want) {
257			t.Errorf("new merge sources = %+v, want %+v", got, want)
258		}
